  "prediction_basis_card_ids": ["C160", "C185", "C205", "C139", "C08"],
  "claims": [
    {
      "claim": "Neostigmine, a close quaternary ammonium carbamate analog, showed only 12.8% absorption from rat jejunum over 2 h and 6.6% of the dose trapped in the gut wall after 3 h, indicating substantial presystemic loss for this chemotype.",
      "card_ids": ["C160", "C185"]
    },
    {
      "claim": "Neostigmine is a P-gp substrate with an efflux ratio of 2.2 in MDR1-MDCKII monolayers, adding gut-wall efflux as a mechanism that limits systemic entry.",
      "card_ids": ["C205"]
    },
    {
      "claim": "Physostigmine, another carbamate acetylcholinesterase inhibitor, is reported to have poor oral bioavailability, supporting a low F for the carbamate class.",
      "card_ids": ["C08"]
    },
    {
      "claim": "The L5 neostigmine records strengthen the absorption-liability evidence but do not provide a direct pyridostigmine F measurement.",
      "card_ids": ["C160", "C185", "C205"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C160", "C185", "C205"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for pyridostigmine in any supplied record.",
    "No matched oral versus IV exposure data for pyridostigmine.",
    "Neostigmine absorption is from rat jejunum single-loop, not whole-intestinal or human F.",
    "Exact salt form and counterion are not specified.",
    "Property tool reports neutral fraction 1 despite the formal quaternary charge, adding uncertainty.",
    "The threshold is borderline and F may be near 20%."
  ],
  "decision_summary": "Prediction remains low. L5 neostigmine records show limited jejunal absorption, gut-wall trapping, and modest P-gp efflux, strengthening the presystemic-loss evidence for this quaternary ammonium carbamate, while no direct pyridostigmine F measurement is available."
}

